import math

def diagonal_gaussian_kl(mu, logvar):
    if not mu or len(mu) != len(logvar):
        raise ValueError('expected equal, nonempty vectors')
    if not all(math.isfinite(x) for x in list(mu)+list(logvar)):
        raise ValueError('nonfinite distribution parameter')
    return 0.5 * sum(m*m + math.exp(v) - 1.0 - v for m,v in zip(mu,logvar))

