import math
import torch

def training_pair(actions, noise, time, family):
    if (actions.ndim != 3 or actions.shape != noise.shape
            or time.shape != actions.shape[:1]):
        raise ValueError('shape mismatch')
    if not all(bool(torch.isfinite(x).all()) for x in (actions, noise, time)):
        raise ValueError('nonfinite training input')
    if bool(((time < 0) | (time > 1)).any()):
        raise ValueError('time outside [0,1]')
    t = time[:, None, None]
    if family == 'flow':
        return (1-t)*noise+t*actions, actions-noise
    if family == 'diffusion':
        return (math.pi*t/2).cos()*actions+(math.pi*t/2).sin()*noise, noise
    raise ValueError('unknown family')

def masked_policy_mse(pred, target, valid):
    if (pred.ndim != 3 or pred.shape != target.shape
            or valid.shape != pred.shape or valid.dtype != torch.bool):
        raise ValueError('shape or mask type mismatch')
    if not bool(valid.any()):
        raise ValueError('no supervised coordinates')
    p, y = pred[valid], target[valid]
    if not bool(torch.isfinite(p).all() & torch.isfinite(y).all()):
        raise ValueError('nonfinite supervised coordinate')
    return (p-y).square().mean()
